#!/usr/bin/env python3
"""
Standalone test for the separability matrix fix.
This copies the relevant functions to test without importing astropy.
"""

import numpy as np

# Mock classes to simulate astropy models
class Model:
    def __init__(self, n_inputs, n_outputs, separable=True):
        self.n_inputs = n_inputs
        self.n_outputs = n_outputs
        self.separable = separable

    def _calculate_separability_matrix(self):
        return NotImplemented

class CompoundModel(Model):
    def __init__(self, left, right, op):
        self.left = left
        self.right = right
        self.op = op
        if op == '&':
            self.n_inputs = left.n_inputs + right.n_inputs
            self.n_outputs = left.n_outputs + right.n_outputs
        super().__init__(self.n_inputs, self.n_outputs, True)

# Copy the relevant functions from separable.py with the fix applied
def _compute_n_outputs(left, right):
    """Compute the number of outputs of two models."""
    if isinstance(left, Model):
        lnout = left.n_outputs
    else:
        lnout = left.shape[0]
    if isinstance(right, Model):
        rnout = right.n_outputs
    else:
        rnout = right.shape[0]
    noutp = lnout + rnout
    return noutp

def _coord_matrix(model, pos, noutp):
    """Create an array representing inputs and outputs of a simple model."""
    if not model.separable:
        mat = np.zeros((noutp, model.n_inputs))
        if pos == 'left':
            mat[:model.n_outputs, : model.n_inputs] = 1
        else:
            mat[-model.n_outputs:, -model.n_inputs:] = 1
    else:
        mat = np.zeros((noutp, model.n_inputs))
        for i in range(model.n_inputs):
            mat[i, i] = 1
        if pos == 'right':
            mat = np.roll(mat, (noutp - model.n_outputs))
    return mat

def _cstack(left, right):
    """Function corresponding to '&' operation - WITH FIX APPLIED."""
    noutp = _compute_n_outputs(left, right)

    if isinstance(left, Model):
        cleft = _coord_matrix(left, 'left', noutp)
    else:
        cleft = np.zeros((noutp, left.shape[1]))
        cleft[: left.shape[0], : left.shape[1]] = left
    if isinstance(right, Model):
        cright = _coord_matrix(right, 'right', noutp)
    else:
        cright = np.zeros((noutp, right.shape[1]))
        # FIXED LINE: Use 'right' instead of '1'
        cright[-right.shape[0]:, -right.shape[1]:] = right

    return np.hstack([cleft, cright])

def _separable(transform):
    """Calculate the separability of outputs."""
    if (transform_matrix := transform._calculate_separability_matrix()) is not NotImplemented:
        return transform_matrix
    elif isinstance(transform, CompoundModel):
        sepleft = _separable(transform.left)
        sepright = _separable(transform.right)
        return _operators[transform.op](sepleft, sepright)
    elif isinstance(transform, Model):
        return _coord_matrix(transform, 'left', transform.n_outputs)

# Operator mapping
_operators = {'&': _cstack}

def separability_matrix(transform):
    """Compute the correlation between outputs and inputs."""
    if transform.n_inputs == 1 and transform.n_outputs > 1:
        return np.ones((transform.n_outputs, transform.n_inputs), dtype=np.bool_)
    separable_matrix = _separable(transform)
    separable_matrix = np.where(separable_matrix != 0, True, False)
    return separable_matrix

def test_fix():
    print("Testing the separability matrix fix")
    print("=" * 50)

    # Create mock models equivalent to the original issue:
    # Linear1D(10) & Linear1D(5) 
    linear1 = Model(n_inputs=1, n_outputs=1, separable=True)
    linear2 = Model(n_inputs=1, n_outputs=1, separable=True)
    cm = CompoundModel(linear1, linear2, '&')

    # Pix2Sky_TAN() (2 inputs, 2 outputs, not separable)
    pix2sky = Model(n_inputs=2, n_outputs=2, separable=False)

    print("1. Simple compound model (Linear1D & Linear1D):")
    cm_result = separability_matrix(cm)
    print(f"Result:\n{cm_result}")
    expected_cm = np.array([[True, False], [False, True]])
    print(f"Expected:\n{expected_cm}")
    print(f"✓ Correct: {np.array_equal(cm_result, expected_cm)}")
    print()

    print("2. Complex model (Pix2Sky_TAN & Linear1D & Linear1D):")
    temp = CompoundModel(pix2sky, linear1, '&')
    complex_model = CompoundModel(temp, linear2, '&')
    complex_result = separability_matrix(complex_model)
    print(f"Result:\n{complex_result}")
    expected_complex = np.array([[True, True, False, False],
                                [True, True, False, False], 
                                [False, False, True, False],
                                [False, False, False, True]])
    print(f"Expected:\n{expected_complex}")
    print(f"✓ Correct: {np.array_equal(complex_result, expected_complex)}")
    print()

    print("3. Nested model (Pix2Sky_TAN & (Linear1D & Linear1D)):")
    nested_model = CompoundModel(pix2sky, cm, '&')
    nested_result = separability_matrix(nested_model)
    print(f"Result:\n{nested_result}")
    print(f"Expected (same as complex):\n{expected_complex}")

    is_fixed = np.array_equal(nested_result, expected_complex)
    print(f"✓ Fixed: {is_fixed}")

    if is_fixed:
        print("\n🎉 SUCCESS: The fix resolves the nested compound model issue!")
    else:
        print("\n❌ FAILURE: Issue still exists")

    return is_fixed

if __name__ == "__main__":
    test_fix()

